    def tokenize(s):
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            if c.isspace():
                i += 1
                continue
            if c.isdigit():
                j = i
                while j < n and s[j].isdigit():
                    j += 1
                tokens.append(('NUM', int(s[i:j])))
                i = j
                continue
            if c in '+-*/()':
                tokens.append((c, c))
                i += 1
                continue
            raise ValueError(f"Unexpected character: {c}")
        return tokens

    tokens = tokenize(expr)
    pos = [0]

    def peek():
        if pos[0] < len(tokens):
            return tokens[pos[0]]
        return None

    def advance():
        tok = tokens[pos[0]]
        pos[0] += 1
        return tok

    def idiv(a, b):
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        return q

    def parse_primary():
        tok = peek()
        if tok is None:
            raise ValueError("Unexpected end of expression")
        if tok[0] == 'NUM':
            advance()
            return tok[1]
        if tok[0] == '(':
            advance()
            val = parse_expr()
            tok2 = peek()
            if tok2 is None or tok2[0] != ')':
                raise ValueError("Expected closing parenthesis")
            advance()
            return val
        raise ValueError(f"Unexpected token: {tok}")

    def parse_unary():
        tok = peek()
        if tok is not None and tok[0] == '-':
            advance()
            val = parse_unary()
            return -val
        return parse_primary()

    def parse_term():
        val = parse_unary()
        while True:
            tok = peek()
            if tok is not None and tok[0] in ('*', '/'):
                advance()
                rhs = parse_unary()
                if tok[0] == '*':
                    val = val * rhs
                else:
                    val = idiv(val, rhs)
            else:
                break
        return val

    def parse_expr():
        val = parse_term()
        while True:
            tok = peek()
            if tok is not None and tok[0] in ('+', '-'):
                advance()
                rhs = parse_term()
                if tok[0] == '+':
                    val = val + rhs
                else:
                    val = val - rhs
            else:
                break
        return val

    result = parse_expr()
    if pos[0] != len(tokens):
        raise ValueError("Unexpected trailing tokens")
    return result

